using Microsoft.AspNetCore.Mvc;namespace LibraryApi.Controllers;[ApiController][Route("api/auth")]public class AuthController:ControllerBase{public record LoginRequest(string Email,string Password);[HttpPost("login")]public IActionResult Login(LoginRequest r){if(r.Email=="admin@library.com"&&r.Password=="admin123")return Ok(new{token="demo-library-token",user=new{name="Library Admin",email=r.Email}});return Unauthorized(new{message="Invalid email or password"});}}
